-- Release D: exact saved roles and canonical consequence replay.
-- Synthetic identities only, ordinary authenticated writers, no HTTP/model calls.
-- Run the entire transaction; every fixture is rolled back.
begin;
set local lock_timeout='5s';
set local statement_timeout='60s';
do $$
declare
 actor uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); solution uuid:=gen_random_uuid(); turn_id uuid:=gen_random_uuid();
 project text; claim jsonb; material jsonb; construction jsonb; need jsonb; payload jsonb; saved jsonb; before_draft jsonb; after_draft jsonb; work jsonb; item jsonb; ready jsonb;
 params jsonb; data jsonb; base jsonb:='{"record_id":null,"expected_revision":0,"expected_updated_at":null,"request_quote":"Save a cut plan"}'::jsonb; msg text:='Release D fixture: save explicit roles and continue the same needs';
begin
 insert into auth.users(id,email,email_confirmed_at) values(actor,actor::text||'@release-d.invalid',now()),(outsider,outsider::text||'@release-d.invalid',now());
 perform set_config('request.jwt.claims',jsonb_build_object('sub',actor)::text,true);
 set local role authenticated;
 project:=bob.create_project('{"name":"Release D rollback-only fixture"}'::jsonb)->>'id';
 perform bob.solution_command(project,'create',solution,0,jsonb_build_object('area_id',null,'title','Synthetic role fixture','description','Rollback only','assumptions','No physical evidence','tradeoffs','Fixture','measurements','[]'::jsonb,'design_intent','{"version":1,"purpose":"construction","summary":"Synthetic isolated construction with the fixture dimensions and selected material.","references":[],"features":[{"id":"fixture_form","description":"Preserve the fixture assembly, dimensions and parts.","basis":"project_record","source_ref":null}],"choices":[{"id":"fixture_design","question":"Which direction should this synthetic output develop?","alternatives":["The explicitly described fixture assembly"],"recommendation":"Develop the fixture assembly.","basis":"The isolated test fixture specifies its dimensions and material.","consequences":"The output is a synthetic concept; joints, products and fabrication still require applicable checks.","geometry_dependency":true,"status":"resolved","selected_direction":"The explicitly described fixture assembly","decision_authority":"bob","decision_basis":"The test delegates the reversible fixture design to Bob.","deferral":null}],"alignment":{"status":"aligned","basis":"The isolated test explicitly selects this fixture direction and output purpose."}}'::jsonb));
 perform bob.solution_command(project,'select',solution,0,'{"solution_revision":1,"reason":"Synthetic release test"}'::jsonb);
 set local role service_role;
 claim:=bob.bob_claim_turn(project,actor,turn_id,msg);
 set local role authenticated;
 base:=base||jsonb_build_object('request_quote',msg);
 material:=bob.bob_project_write_v16(project,(claim->>'thread_id')::uuid,turn_id,(claim->>'generation')::bigint,
 base||'{"kind":"catalog","data":{"action":"ensure","key":"d-material","kind":"material","name":"Synthetic plywood 18","aliases":[],"profile_code":"sheet_stock","profile_revision":1,"categories":["wood.plywood","sheet"],"properties":{"thickness":{"value":"18","unit":"mm","truth":"provided_spec","parameter":null,"note":""}},"material_id":null,"material_revision":null,"notes":"Rollback-only fixture","source_kind":"design_choice","source_quote":"save explicit roles","source_seq":null}}'::jsonb);
 data:=replace(replace(('{"key":"construction","title":"Two-part bracket","description":"Concept","area_id":null,"target_revision":1,"change_note":"Fixture","recipe":{"contract_version":1,"units":"mm","assembly_id":"bracket","definitions":[{"id":"base","primitive":"box","material_ref":null,"x_mm":200,"y_mm":100,"z_mm":18},{"id":"upright","primitive":"box","material_ref":null,"x_mm":18,"y_mm":100,"z_mm":100}],"instances":[{"id":"foot","definition_id":"base","placement":{"x":0,"y":0,"z":0,"rx":0,"ry":0,"rz":0}},{"id":"back","definition_id":"upright","placement":{"x":0,"y":0,"z":18,"rx":0,"ry":0,"rz":0}}],"views":["front"]},"parameters":{"version":1,"project_id":"p_d4916f356a8e498db9e77edc1b124e22","coverage":"complete","precision":"decimal_6","coordinate_system":{"version":1,"id":"bracket","length_unit":"mm","angle_unit":"deg","origin":[0,0,0],"positive_axes":[[1,0,0],[0,1,0],[0,0,1]],"rotation":"build123d_0.13_intrinsic_xyz","definition_origins":{"box":"minimum_corner","cylinder":"xy_center_z_min","tube":"xy_center_z_min"},"instance_parent":"assembly","cut_parent":"definition","frame_identity":"artifact_revision_and_recipe_path","views":{"front":{"toward_camera":[0,-1,0],"up":[0,0,1]},"right":{"toward_camera":[1,0,0],"up":[0,0,1]},"top":{"toward_camera":[0,0,1],"up":[0,1,0]},"isometric":{"toward_camera":[1,-1,1],"up":[0,0,1]}}},"frames":[],"nodes":[{"id":"p88453693d4c933c58efa","role":"decision","value":200,"unit":"mm","reason":"Explicit synthetic fixture design choice","normalized":{"value":200,"unit":"mm"},"sources":[]},{"id":"p7f1e0cb30f6f21f65dc0","role":"decision","value":100,"unit":"mm","reason":"Explicit synthetic fixture design choice","normalized":{"value":100,"unit":"mm"},"sources":[]},{"id":"p993edf7acd62221d4149","role":"decision","value":18,"unit":"mm","reason":"Explicit synthetic fixture design choice","normalized":{"value":18,"unit":"mm"},"sources":[]},{"id":"pc30297a78264eb18c760","role":"decision","value":18,"unit":"mm","reason":"Explicit synthetic fixture design choice","normalized":{"value":18,"unit":"mm"},"sources":[]},{"id":"pbb3f174c3619ae457893","role":"decision","value":100,"unit":"mm","reason":"Explicit synthetic fixture design choice","normalized":{"value":100,"unit":"mm"},"sources":[]},{"id":"p3d71898760dde1d9bfd1","role":"decision","value":100,"unit":"mm","reason":"Explicit synthetic fixture design choice","normalized":{"value":100,"unit":"mm"},"sources":[]},{"id":"p5d99496c1ec3d54dbe82","role":"decision","value":0,"unit":"mm","reason":"Explicit synthetic fixture design choice","normalized":{"value":0,"unit":"mm"},"sources":[]},{"id":"p4c445a25f7a11eab686a","role":"decision","value":0,"unit":"mm","reason":"Explicit synthetic fixture design choice","normalized":{"value":0,"unit":"mm"},"sources":[]},{"id":"p2ec3cc09667bbef0b71a","role":"decision","value":0,"unit":"mm","reason":"Explicit synthetic fixture design choice","normalized":{"value":0,"unit":"mm"},"sources":[]},{"id":"p20f803bbefee1e417742","role":"decision","value":0,"unit":"deg","reason":"Explicit synthetic fixture design choice","normalized":{"value":0,"unit":"deg"},"sources":[]},{"id":"p03792053ce4afff1ae2a","role":"decision","value":0,"unit":"deg","reason":"Explicit synthetic fixture design choice","normalized":{"value":0,"unit":"deg"},"sources":[]},{"id":"p1f886ae9093e1a0a7a26","role":"decision","value":0,"unit":"deg","reason":"Explicit synthetic fixture design choice","normalized":{"value":0,"unit":"deg"},"sources":[]},{"id":"pcd04f19df106991212fc","role":"decision","value":0,"unit":"mm","reason":"Explicit synthetic fixture design choice","normalized":{"value":0,"unit":"mm"},"sources":[]},{"id":"p254e1556088cb3e131c8","role":"decision","value":0,"unit":"mm","reason":"Explicit synthetic fixture design choice","normalized":{"value":0,"unit":"mm"},"sources":[]},{"id":"p08d248d413f3d16f033d","role":"decision","value":18,"unit":"mm","reason":"Explicit synthetic fixture design choice","normalized":{"value":18,"unit":"mm"},"sources":[]},{"id":"pf9708a068831b07bae33","role":"decision","value":0,"unit":"deg","reason":"Explicit synthetic fixture design choice","normalized":{"value":0,"unit":"deg"},"sources":[]},{"id":"p2a61c0b9a2e74c0ee097","role":"decision","value":0,"unit":"deg","reason":"Explicit synthetic fixture design choice","normalized":{"value":0,"unit":"deg"},"sources":[]},{"id":"p55711e897e655d9ae5fb","role":"decision","value":0,"unit":"deg","reason":"Explicit synthetic fixture design choice","normalized":{"value":0,"unit":"deg"},"sources":[]}],"bindings":[{"path":"definitions/base/x_mm","node":"p88453693d4c933c58efa"},{"path":"definitions/base/y_mm","node":"p7f1e0cb30f6f21f65dc0"},{"path":"definitions/base/z_mm","node":"p993edf7acd62221d4149"},{"path":"definitions/upright/x_mm","node":"pc30297a78264eb18c760"},{"path":"definitions/upright/y_mm","node":"pbb3f174c3619ae457893"},{"path":"definitions/upright/z_mm","node":"p3d71898760dde1d9bfd1"},{"path":"instances/foot/placement/x","node":"p5d99496c1ec3d54dbe82"},{"path":"instances/foot/placement/y","node":"p4c445a25f7a11eab686a"},{"path":"instances/foot/placement/z","node":"p2ec3cc09667bbef0b71a"},{"path":"instances/foot/placement/rx","node":"p20f803bbefee1e417742"},{"path":"instances/foot/placement/ry","node":"p03792053ce4afff1ae2a"},{"path":"instances/foot/placement/rz","node":"p1f886ae9093e1a0a7a26"},{"path":"instances/back/placement/x","node":"pcd04f19df106991212fc"},{"path":"instances/back/placement/y","node":"p254e1556088cb3e131c8"},{"path":"instances/back/placement/z","node":"p08d248d413f3d16f033d"},{"path":"instances/back/placement/rx","node":"pf9708a068831b07bae33"},{"path":"instances/back/placement/ry","node":"p2a61c0b9a2e74c0ee097"},{"path":"instances/back/placement/rz","node":"p55711e897e655d9ae5fb"}]},"materials":[{"definition_id":"base","material_id":"a22e6833-fb8b-45dc-95ab-17681de0b665","material_revision":1,"part_id":null,"part_revision":null},{"definition_id":"upright","material_id":"a22e6833-fb8b-45dc-95ab-17681de0b665","material_revision":1,"part_id":null,"part_revision":null}],"joints":[{"id":"join","method":"glued_butt","first":{"instance_id":"foot","face":"z_max"},"second":{"instance_id":"back","face":"z_min"},"reason":"Concept"}],"open_questions":["Hardware/access unknown"],"instance_policy":{"version":1,"instances":[{"instance_id":"foot","role":"build_part","quantity_policy":"manufacture","reason":"The synthetic fixture explicitly requests this instance as a newly manufactured part."},{"instance_id":"back","role":"build_part","quantity_policy":"manufacture","reason":"The synthetic fixture explicitly requests this instance as a newly manufactured part."}]}}'::jsonb)::text,'p_d4916f356a8e498db9e77edc1b124e22',project),'a22e6833-fb8b-45dc-95ab-17681de0b665',material->>'recordId')::jsonb;
 construction:=bob.bob_project_write_v16(project,(claim->>'thread_id')::uuid,turn_id,(claim->>'generation')::bigint,base||jsonb_build_object('kind','construction','data',data));
 before_draft:=bob.read_construction_draft(project,(construction->>'recordId')::uuid,1,null);
 if before_draft->'instance_policy' is distinct from data->'instance_policy' then raise exception 'd_policy_save_read'; end if;
 for data in select jsonb_build_object('name',definition_id||' synthetic blank','category','Timber','area_id',null,'task_id',null,'waste_percent','0','purchase_increment','1','assumptions','Fixture','artifact_id',construction->>'recordId','artifact_revision',1,'target_revision',1,'definition_id',definition_id,'quantity_mode','pieces','stock_allocations','[]'::jsonb,'component_allocations','[]'::jsonb,'change_note','Explicit counted fixture') from unnest(array['base','upright']) definition_id loop
  need:=bob.bob_project_write_v16(project,(claim->>'thread_id')::uuid,turn_id,(claim->>'generation')::bigint,base||jsonb_build_object('kind','operational','data',jsonb_build_object('resource','cad_requirement','action','create','fields',data)));
 end loop;
 payload:=base||jsonb_build_object('kind','construction_roles','record_id',construction->>'recordId','expected_revision',1,'data','{"key":"d-retain","computed":null,"changes":[{"instance_id":"back","role":"existing_part","quantity_policy":"retain","reason":"Explicit synthetic existing member"}],"change_note":"Retain this synthetic member"}'::jsonb);
 saved:=bob.bob_project_write_v16(project,(claim->>'thread_id')::uuid,turn_id,(claim->>'generation')::bigint,payload);
 set constraints all immediate;
 after_draft:=bob.read_construction_draft(project,(construction->>'recordId')::uuid,2,null);
 if after_draft->'recipe' is distinct from before_draft->'recipe' or after_draft->'parameters' is distinct from before_draft->'parameters' or after_draft->'materials' is distinct from before_draft->'materials' or after_draft->'joints' is distinct from before_draft->'joints' then raise exception 'd_role_changed_geometry'; end if;
 if saved->>'revision'<>'2' or after_draft#>>'{instance_policy,instances,0,role}' is distinct from 'existing_part' then raise exception 'd_role_revision'; end if;
 if bob.bob_project_write_v16(project,(claim->>'thread_id')::uuid,turn_id,(claim->>'generation')::bigint,payload) is distinct from saved then raise exception 'd_role_retry'; end if;
 work:=bob.read_construction_changes(project,(construction->>'recordId')::uuid,2,null);
 if work->>'total'<>'2' or work->>'pending'<>'2' then raise exception 'd_capture_missing'; end if;
 for item in select value from jsonb_array_elements(work->'items') loop
  params:=base||jsonb_build_object('kind','construction_consequence','record_id',construction->>'recordId','expected_revision',2,'data',jsonb_build_object('key','d-continue-'||(item->>'id'),'item_id',item->>'id','action','recalculate','review_note',null,'output_revision',null,'computed',null,'change_note','Continue the saved fixture item'));
  ready:=bob.prepare_construction_consequence(project,(claim->>'thread_id')::uuid,turn_id,(claim->>'generation')::bigint,params);
  if ready->>'status'<>'ready' then raise exception 'd_continue_not_ready: %',ready->>'status'; end if;
  need:=bob.bob_project_write_v16(project,(claim->>'thread_id')::uuid,turn_id,(claim->>'generation')::bigint,params);
  if need->>'recordId' is distinct from item->>'output_id' or need->>'revision'<>'2' then raise exception 'd_output_identity'; end if;
  if bob.bob_project_write_v16(project,(claim->>'thread_id')::uuid,turn_id,(claim->>'generation')::bigint,params) is distinct from need then raise exception 'd_continue_retry'; end if;
 end loop;
 work:=bob.read_construction_changes(project,(construction->>'recordId')::uuid,2,null);
 if work->>'status'<>'complete' or work->>'pending'<>'0' then raise exception 'd_work_incomplete'; end if;
 if (select count(*) from bob.material_requirement_revisions where project_id=project and revision=1 and not archived and required_quantity=1)<>2 then raise exception 'd_need_history'; end if;
 if (select count(*) from bob.material_requirement_revisions where project_id=project and revision=2 and archived)<>1 then raise exception 'd_retirement_missing'; end if;
 begin
  update bob.artifact_construction_instance_policies set policy='{}' where project_id=project;
  raise exception 'd_raw_policy_write_allowed';
 exception when insufficient_privilege then null; end;
 begin
  update bob.construction_change_items set state='reviewed' where project_id=project;
  raise exception 'd_raw_queue_write_allowed';
 exception when insufficient_privilege then null; end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider)::text,true);
 begin
  perform bob.read_construction_changes(project,(construction->>'recordId')::uuid,2,null);
  raise exception 'd_outsider_read_allowed';
 exception when insufficient_privilege then null; end;
 if exists(select 1 from bob.construction_change_items where project_id=project) then raise exception 'd_outsider_rls'; end if;
 reset role;
end $$;
rollback;
